SELECT id, ends_on, discount_pct, NTILE(10) OVER (PARTITION BY channel ORDER BY discount_pct DESC, id) AS discount_pct_bucket, LAG(discount_pct, 1) OVER (PARTITION BY channel ORDER BY discount_pct, id) AS prev_discount_pct, LAST_VALUE(channel, TRUE) OVER (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel FROM promotions WHERE YEAR(starts_on) >= 2025
